  for(const e of L){const last=out.find(o=>o.text===e.text&&addDays(o.end||o.date,1)>=e.date&&o.date<=e.date);
    if(last){if((e.end||e.date)>(last.end||last.date))last.end=e.end||e.date;continue}out.push(Object.assign({},e))}
  const runs=out.filter(o=>o.end&&o.end>o.date&&NL_CLOSED.test(o.text));
