// a date, or the first and last day of a run, as families read it
const nlWhen=(c,short)=>{if(!c||!c.date)return "";const f=d=>short?parseIso(d).toLocaleDateString("en-US",{weekday:"short",month:"short",day:"numeric"}):nlDay(d);return c.end&&c.end>c.date?f(c.date)+" to "+f(c.end):f(c.date)};
const nlDay=d=>parseIso(d).toLocaleDateString("en-US",{weekday:"long",month:"long",day:"numeric"});
// a calendar title that joins two phrases with a hyphen, such as Thanksgiving Break-School Closed, reads as
