const NL_C={ink:"#1B2920",moss:"#2B5A40",muted:"#5B6B61",line:"#DCE3DA",link:"#245B78",soft:"#F3F6F2",warm:"#FBF3E4",amber:"#9A5B07"};
const nlEP=(t,st)=>`<p style="margin:0 0 14px;${st||""}">${t}</p>`;
