const nlEParas=t=>String(t||"").trim().split(/\n\s*\n/).filter(Boolean).map(p=>nlEP(p.split("\n").map(l=>/^https?:\/\/\S+$/.test(l.trim())?nlLink(l.trim()):nlEsc(l)).join("<br>"))).join("");
