      if(t.bonus&&!short)inner+=`<div style="margin:14px 0;padding:12px 14px;background:${NL_C.warm};border-left:4px solid ${NL_C.amber};border-radius:6px"><b style="color:${NL_C.amber}">Bonus for school.</b> ${nlEsc(t.bonus)}</div>`;
