      <div class="nlrow" style="flex-wrap:wrap;gap:6px 14px">${names.map(n=>`<label class="nlcheck" style="margin:0"><input type="checkbox" data-nlfarmpick="${esc(n)}" ${pick.has(gKey(n))?"checked":""}> ${esc(n)}</label>`).join("")}</div>
